    "counter_runs": {
      "item": [
        "Run A base builder: EMPTY_OK=pass REBUILD_OK=pass ESCAPE_ENTRY=pass(refused) HELDOUT_OK=pass; FOREIGN=fail(rc=0, orphans deleted: foreign gone=True); SYMLINK_OUT=fail(rc=0, expected refusal)(target-dir-written!); SYMLINK_CACHE=fail(rc=0, expected refusal); FIFO_TXT=fail(rc=1, reason [...] absent in '... refused S571: no defined text form ...'); DEVZERO_TXT=fail(rc=1, reason [...] absent in '... refused S581: no defined text form ...'); FAT_RAW=fail(rc=1, reason ['SIZE'] absent in '... capture-text refused f96cbd6d82dbae8a8e2c6223.raw: ole-malformed: sector shift 0, mini shift 0'); MANY_QUOTES=fail(rc=0, expected refusal); BEFORE_FOREIGN=deleted; SUMMARY OK=4/4 REFUSE=0/7 BEFORE_FOREIGN=deleted DENIED=0/0; C1=FAIL (exit 1) — reproduces controls/c1-before.txt exactly",
